const response = $input.first().json;
const strategies = response.strategies || response || [];

// Create individual items for each strategy
const items = strategies.map(s => ({
  json: {
    strategyId: s.id || s.name,
    strategyName: s.name || s.id,
    category: s.category || 'unknown',
    currentParams: s.parameters || s.params || {},
    baselineMetrics: s.baseline || {
      targetWinRate: 55,
      targetSharpe: 1.0,
      maxDrawdown: 10,
      minProfitFactor: 1.2
    },
    enabled: s.enabled !== false
  }
}));

// If no strategies, return placeholder
if (items.length === 0) {
  return [{
    json: {
      error: 'No active strategies found',
      strategies: []
    }
  }];
}

return items;

const batchData = $('SplitInBatches: Process Each Strategy').first().json;
const tradesData = $('HTTP: Fetch Strategy Trades (30 Days)').first()?.json || {};
const rulesData = $('HTTP: Fetch Strategy Rules').first()?.json || {};
const proposalsData = $('HTTP: Fetch Previous Proposals').first()?.json || {};

const trades = tradesData.trades || [];
const rules = rulesData.rules || rulesData;
const previousProposals = proposalsData.proposals || [];
const baseline = batchData.baselineMetrics || {};

// Calculate key metrics
const metrics = {
  tradeCount: trades.length,
  winningTrades: 0,
  losingTrades: 0,
  totalPnL: 0,
  grossProfit: 0,
  grossLoss: 0,
  avgWin: 0,
  avgLoss: 0,
  largestWin: 0,
  largestLoss: 0,
  winRate: 0,
  profitFactor: 0,
  avgHoldTime: 0,
  returns: [],
  drawdowns: [],
  consecutiveLosses: 0,
  maxConsecutiveLosses: 0,
  byTimeOfDay: {},
  byDayOfWeek: {}
};

if (trades.length === 0) {
  return {
    json: {
      strategy: batchData,
      metrics: { ...metrics, error: 'No trades in period' },
      rules: rules,
      previousProposals: previousProposals,
      needsAnalysis: false
    }
  };
}

// Process each trade
let runningPnL = 0;
let peak = 0;
let currentLossStreak = 0;

trades.forEach(trade => {
  const pnl = parseFloat(trade.pnl) || 0;
  metrics.totalPnL += pnl;
  runningPnL += pnl;

  // Track peak and drawdown
  if (runningPnL > peak) peak = runningPnL;
  const drawdown = peak > 0 ? ((peak - runningPnL) / peak) * 100 : 0;
  metrics.drawdowns.push(drawdown);

  if (pnl > 0) {
    metrics.winningTrades++;
    metrics.grossProfit += pnl;
    metrics.largestWin = Math.max(metrics.largestWin, pnl);
    currentLossStreak = 0;
  } else {
    metrics.losingTrades++;
    metrics.grossLoss += Math.abs(pnl);
    metrics.largestLoss = Math.min(metrics.largestLoss, pnl);
    currentLossStreak++;
    metrics.maxConsecutiveLosses = Math.max(metrics.maxConsecutiveLosses, currentLossStreak);
  }

  // Calculate return percentage
  const entryValue = parseFloat(trade.entry_price) * (parseFloat(trade.quantity) || 1);
  const returnPct = entryValue > 0 ? (pnl / entryValue) * 100 : 0;
  metrics.returns.push(returnPct);

  // Hold time
  if (trade.entry_time && trade.exit_time) {
    const holdMs = new Date(trade.exit_time) - new Date(trade.entry_time);
    metrics.avgHoldTime += holdMs / 60000; // minutes
  }

  // Time of day analysis
  if (trade.entry_time) {
    const hour = new Date(trade.entry_time).getHours();
    const timeKey = hour < 9 ? 'premarket' : hour < 11 ? 'opening' : hour < 14 ? 'midday' : hour < 16 ? 'closing' : 'afterhours';
    if (!metrics.byTimeOfDay[timeKey]) metrics.byTimeOfDay[timeKey] = { trades: 0, pnl: 0, wins: 0 };
    metrics.byTimeOfDay[timeKey].trades++;
    metrics.byTimeOfDay[timeKey].pnl += pnl;
    if (pnl > 0) metrics.byTimeOfDay[timeKey].wins++;

    // Day of week
    const day = new Date(trade.entry_time).getDay();
    const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const dayKey = dayNames[day];
    if (!metrics.byDayOfWeek[dayKey]) metrics.byDayOfWeek[dayKey] = { trades: 0, pnl: 0, wins: 0 };
    metrics.byDayOfWeek[dayKey].trades++;
    metrics.byDayOfWeek[dayKey].pnl += pnl;
    if (pnl > 0) metrics.byDayOfWeek[dayKey].wins++;
  }
});

// Calculate derived metrics
metrics.winRate = metrics.tradeCount > 0 ? (metrics.winningTrades / metrics.tradeCount) * 100 : 0;
metrics.avgWin = metrics.winningTrades > 0 ? metrics.grossProfit / metrics.winningTrades : 0;
metrics.avgLoss = metrics.losingTrades > 0 ? metrics.grossLoss / metrics.losingTrades : 0;
metrics.profitFactor = metrics.grossLoss > 0 ? metrics.grossProfit / metrics.grossLoss : metrics.grossProfit > 0 ? 999 : 0;
metrics.avgHoldTime = metrics.tradeCount > 0 ? metrics.avgHoldTime / metrics.tradeCount : 0;
metrics.maxDrawdown = Math.max(...metrics.drawdowns, 0);

// Calculate Sharpe Ratio (simplified)
const avgReturn = metrics.returns.length > 0 ? metrics.returns.reduce((a, b) => a + b, 0) / metrics.returns.length : 0;
const stdDev = metrics.returns.length > 1 ? Math.sqrt(
  metrics.returns.reduce((sum, r) => sum + Math.pow(r - avgReturn, 2), 0) / (metrics.returns.length - 1)
) : 1;
metrics.sharpeRatio = stdDev > 0 ? (avgReturn * Math.sqrt(252)) / stdDev : 0; // Annualized

// Risk-Reward Ratio
metrics.riskRewardRatio = metrics.avgLoss > 0 ? metrics.avgWin / metrics.avgLoss : 0;

// Expectancy
metrics.expectancy = (metrics.winRate / 100) * metrics.avgWin - ((100 - metrics.winRate) / 100) * metrics.avgLoss;

// Compare to baseline
const comparison = {
  winRateVsTarget: metrics.winRate - (baseline.targetWinRate || 55),
  sharpeVsTarget: metrics.sharpeRatio - (baseline.targetSharpe || 1.0),
  drawdownVsMax: (baseline.maxDrawdown || 10) - metrics.maxDrawdown,
  profitFactorVsTarget: metrics.profitFactor - (baseline.minProfitFactor || 1.2)
};

// Identify underperformance
const issues = [];
if (comparison.winRateVsTarget < -5) issues.push({ type: 'win_rate', severity: 'high', value: metrics.winRate, target: baseline.targetWinRate || 55 });
if (comparison.sharpeVsTarget < -0.3) issues.push({ type: 'sharpe', severity: 'medium', value: metrics.sharpeRatio, target: baseline.targetSharpe || 1.0 });
if (comparison.drawdownVsMax < -5) issues.push({ type: 'drawdown', severity: 'high', value: metrics.maxDrawdown, target: baseline.maxDrawdown || 10 });
if (comparison.profitFactorVsTarget < -0.3) issues.push({ type: 'profit_factor', severity: 'medium', value: metrics.profitFactor, target: baseline.minProfitFactor || 1.2 });
if (metrics.maxConsecutiveLosses >= 5) issues.push({ type: 'loss_streak', severity: 'high', value: metrics.maxConsecutiveLosses, target: 4 });

// Identify worst time periods
let worstTime = null;
Object.entries(metrics.byTimeOfDay).forEach(([time, data]) => {
  const winRate = data.trades > 0 ? (data.wins / data.trades) * 100 : 0;
  if (data.trades >= 3 && winRate < 40 && (!worstTime || winRate < worstTime.winRate)) {
    worstTime = { time, winRate, trades: data.trades, pnl: data.pnl };
  }
});

let worstDay = null;
Object.entries(metrics.byDayOfWeek).forEach(([day, data]) => {
  const winRate = data.trades > 0 ? (data.wins / data.trades) * 100 : 0;
  if (data.trades >= 3 && winRate < 40 && (!worstDay || winRate < worstDay.winRate)) {
    worstDay = { day, winRate, trades: data.trades, pnl: data.pnl };
  }
});

return {
  json: {
    strategy: batchData,
    metrics: {
      ...metrics,
      returns: undefined, // Don't pass large arrays
      drawdowns: undefined
    },
    comparison: comparison,
    issues: issues,
    worstTime: worstTime,
    worstDay: worstDay,
    rules: rules,
    previousProposals: previousProposals,
    needsAnalysis: issues.length > 0 || metrics.tradeCount >= 10
  }
};

const data = $json;

const prompt = `You are the Strategy Optimization Specialist for SwjshAK trading system. Analyze this strategy's performance and propose parameter adjustments.

## STRATEGY: ${data.strategy.strategyName}
Category: ${data.strategy.category}
Enabled: ${data.strategy.enabled}

## CURRENT PARAMETERS
${JSON.stringify(data.strategy.currentParams, null, 2)}

## STRATEGY RULES
${typeof data.rules === 'string' ? data.rules : JSON.stringify(data.rules, null, 2)}

## LAST 30 DAYS PERFORMANCE
- Total Trades: ${data.metrics.tradeCount}
- Win Rate: ${data.metrics.winRate.toFixed(1)}% (target: ${data.strategy.baselineMetrics?.targetWinRate || 55}%)
- Profit Factor: ${data.metrics.profitFactor.toFixed(2)} (target: ${data.strategy.baselineMetrics?.minProfitFactor || 1.2})
- Sharpe Ratio: ${data.metrics.sharpeRatio.toFixed(2)} (target: ${data.strategy.baselineMetrics?.targetSharpe || 1.0})
- Max Drawdown: ${data.metrics.maxDrawdown.toFixed(1)}% (max allowed: ${data.strategy.baselineMetrics?.maxDrawdown || 10}%)
- Total P&L: $${data.metrics.totalPnL.toFixed(2)}
- Average Win: $${data.metrics.avgWin.toFixed(2)}
- Average Loss: $${data.metrics.avgLoss.toFixed(2)}
- Risk/Reward: ${data.metrics.riskRewardRatio.toFixed(2)}
- Expectancy: $${data.metrics.expectancy.toFixed(2)}
- Max Consecutive Losses: ${data.metrics.maxConsecutiveLosses}
- Average Hold Time: ${data.metrics.avgHoldTime.toFixed(0)} minutes

## IDENTIFIED ISSUES
${data.issues.map(i => `- [${i.severity.toUpperCase()}] ${i.type}: ${i.value.toFixed(2)} vs target ${i.target}`).join('\n') || 'No critical issues'}

## PERFORMANCE BY TIME OF DAY
${Object.entries(data.metrics.byTimeOfDay || {}).map(([t, d]) => `- ${t}: ${d.trades} trades, $${d.pnl.toFixed(2)}, ${((d.wins/d.trades)*100).toFixed(0)}% win rate`).join('\n') || 'N/A'}

## PERFORMANCE BY DAY OF WEEK
${Object.entries(data.metrics.byDayOfWeek || {}).map(([d, v]) => `- ${d}: ${v.trades} trades, $${v.pnl.toFixed(2)}, ${((v.wins/v.trades)*100).toFixed(0)}% win rate`).join('\n') || 'N/A'}

## WORST PERFORMING PERIODS
${data.worstTime ? `- Time: ${data.worstTime.time} (${data.worstTime.winRate.toFixed(0)}% win rate, ${data.worstTime.trades} trades)` : 'None identified'}
${data.worstDay ? `- Day: ${data.worstDay.day} (${data.worstDay.winRate.toFixed(0)}% win rate, ${data.worstDay.trades} trades)` : ''}

## PREVIOUS PROPOSALS (for context)
${data.previousProposals.slice(0, 3).map(p => `- ${p.date}: ${p.proposal} - Status: ${p.status || 'unknown'}`).join('\n') || 'No previous proposals'}

---

## YOUR TASK

Analyze the strategy performance and propose specific parameter adjustments. Be conservative - small changes that can be tested.

Provide your analysis as JSON:
{
  "overallAssessment": "healthy|needs_tuning|critical|should_disable",
  "confidenceScore": 0-100,
  "primaryIssue": "One sentence describing the main problem or 'Strategy performing well'",
  "proposals": [
    {
      "parameterName": "name of parameter to change",
      "currentValue": "current value",
      "proposedValue": "new value",
      "changeType": "increase|decrease|add|remove|modify",
      "rationale": "Why this change will help",
      "expectedImpact": "What improvement we expect",
      "riskLevel": "low|medium|high",
      "testDuration": "1 week|2 weeks|1 month"
    }
  ],
  "timingRestrictions": [
    {
      "type": "disable_during|reduce_size_during",
      "period": "first_30_min|specific_day|etc",
      "rationale": "Why"
    }
  ],
  "riskAdjustments": {
    "positionSizeChange": "+20%|no_change|-20%|-50%",
    "stopLossAdjustment": "tighten|no_change|widen",
    "takeProfitAdjustment": "lower|no_change|raise"
  },
  "monitoringNotes": ["What to watch after implementing changes"],
  "doNotChange": ["Parameters that are working well and should not be modified"]
}

Be specific and actionable. If the strategy is performing well, say so and propose no changes. If issues exist, propose the minimum changes needed to address them.`;

return {
  json: {
    prompt: prompt,
    strategyData: data
  }
};

const response = $json;
const strategyData = $('Code: Build Tuning Prompt').first().json.strategyData;

let analysis;

try {
  const content = response.content?.[0]?.text || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  analysis = jsonMatch ? JSON.parse(jsonMatch[0]) : { error: 'Could not parse AI response' };
} catch (e) {
  analysis = {
    overallAssessment: 'needs_tuning',
    confidenceScore: 30,
    primaryIssue: 'AI parsing failed - manual review required',
    proposals: [],
    timingRestrictions: [],
    riskAdjustments: { positionSizeChange: 'no_change', stopLossAdjustment: 'no_change', takeProfitAdjustment: 'no_change' },
    monitoringNotes: ['Review raw metrics manually'],
    doNotChange: [],
    _parseError: e.message
  };
}

// Add metadata
analysis.strategyName = strategyData.strategy.strategyName;
analysis.strategyId = strategyData.strategy.strategyId;
analysis.metrics = strategyData.metrics;
analysis.issues = strategyData.issues;
analysis.analyzedAt = new Date().toISOString();

return { json: analysis };

