parameters.jsCode:
const analysis = $json;

// Determine embed color
let embedColor = 3066993; // Green
if (analysis.overallAssessment === 'critical') {
  embedColor = 15158332; // Red
} else if (analysis.overallAssessment === 'needs_tuning') {
  embedColor = 16776960; // Yellow
} else if (analysis.overallAssessment === 'should_disable') {
  embedColor = 10038562; // Purple
}

const fields = [
  {
    name: ':chart_with_upwards_trend: Win Rate',
    value: `${analysis.metrics?.winRate?.toFixed(1) || 0}%`,
    inline: true
  },
  {
    name: ':moneybag: P&L (30d)',
    value: `$${analysis.metrics?.totalPnL?.toFixed(2) || 0}`,
    inline: true
  },
  {
    name: ':dart: Confidence',
    value: `${analysis.confidenceScore || 0}%`,
    inline: true
  }
];

// Add top proposals
if (analysis.proposals?.length > 0) {
  const proposalText = analysis.proposals.slice(0, 3).map((p, i) => 
    `${i + 1}. **${p.parameterName}**: ${p.currentValue} -> ${p.proposedValue} [${p.riskLevel}]`
  ).join('\n');
  fields.push({
    name: ':wrench: Proposed Changes',
    value: proposalText,
    inline: false
  });
}

// Add risk adjustments if any
const riskChanges = [];
if (analysis.riskAdjustments?.positionSizeChange !== 'no_change') {
  riskChanges.push(`Position Size: ${analysis.riskAdjustments.positionSizeChange}`);
}
if (analysis.riskAdjustments?.stopLossAdjustment !== 'no_change') {
  riskChanges.push(`Stop Loss: ${analysis.riskAdjustments.stopLossAdjustment}`);
}
if (riskChanges.length > 0) {
  fields.push({
    name: ':shield: Risk Adjustments',
    value: riskChanges.join('\n'),
    inline: false
  });
}

const embed = {
  title: `:gear: Strategy Tune Proposal: ${analysis.strategyName}`,
  description: `**Assessment:** ${analysis.overallAssessment?.toUpperCase() || 'UNKNOWN'}\n\n${analysis.primaryIssue || 'Review required'}`,
  color: embedColor,
  fields: fields,
  footer: {
    text: 'React with :white_check_mark: to approve or :x: to reject | WF-LEARN-02'
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    embed,
    analysis,
    channelId: process.env.DISCORD_APPROVALS_CHANNEL_ID || 'approvals'
  }
};

// Strategy that's healthy or has no proposals
const analysis = $json;

return {
  json: {
    strategyName: analysis.strategyName,
    strategyId: analysis.strategyId,
    status: 'healthy',
    assessment: analysis.overallAssessment || 'healthy',
    message: analysis.primaryIssue || 'No changes needed',
    metrics: analysis.metrics,
    analyzedAt: analysis.analyzedAt || new Date().toISOString()
  }
};

const data = $json;

return {
  json: {
    strategyName: data.strategy?.strategyName || 'unknown',
    strategyId: data.strategy?.strategyId || 'unknown',
    status: 'skipped',
    reason: data.metrics?.error || 'Insufficient data for analysis',
    tradeCount: data.metrics?.tradeCount || 0
  }
};

const allResults = $input.all();

const summary = {
  totalStrategies: 0,
  healthy: [],
  needsTuning: [],
  critical: [],
  shouldDisable: [],
  skipped: [],
  proposalsCreated: 0,
  analyzedAt: new Date().toISOString()
};

allResults.forEach(item => {
  const data = item.json;
  summary.totalStrategies++;

  if (data.status === 'skipped') {
    summary.skipped.push({ name: data.strategyName, reason: data.reason });
  } else if (data.assessment === 'healthy' || data.status === 'healthy') {
    summary.healthy.push({ name: data.strategyName, metrics: data.metrics });
  } else if (data.assessment === 'critical') {
    summary.critical.push({ name: data.strategyName, issue: data.primaryIssue });
    summary.proposalsCreated++;
  } else if (data.assessment === 'should_disable') {
    summary.shouldDisable.push({ name: data.strategyName, issue: data.primaryIssue });
    summary.proposalsCreated++;
  } else if (data.assessment === 'needs_tuning' || data.proposals?.length > 0) {
    summary.needsTuning.push({ name: data.strategyName, issue: data.primaryIssue, proposalCount: data.proposals?.length || 0 });
    summary.proposalsCreated++;
  }
});

return { json: summary };

const summary = $json;

// Determine overall system health color
let embedColor = 3066993; // Green
if (summary.critical.length > 0 || summary.shouldDisable.length > 0) {
  embedColor = 15158332; // Red
} else if (summary.needsTuning.length > 0) {
  embedColor = 16776960; // Yellow
}

const fields = [
  {
    name: ':white_check_mark: Healthy',
    value: `${summary.healthy.length} strategies`,
    inline: true
  },
  {
    name: ':wrench: Needs Tuning',
    value: `${summary.needsTuning.length} strategies`,
    inline: true
  },
  {
    name: ':warning: Critical',
    value: `${summary.critical.length} strategies`,
    inline: true
  }
];

if (summary.needsTuning.length > 0) {
  fields.push({
    name: ':gear: Strategies Needing Adjustment',
    value: summary.needsTuning.map(s => `- **${s.name}**: ${s.issue?.substring(0, 60) || 'Review needed'}...`).join('\n').substring(0, 1000),
    inline: false
  });
}

if (summary.critical.length > 0) {
  fields.push({
    name: ':rotating_light: Critical Issues',
    value: summary.critical.map(s => `- **${s.name}**: ${s.issue?.substring(0, 60) || 'Critical'}...`).join('\n').substring(0, 500),
    inline: false
  });
}

if (summary.shouldDisable.length > 0) {
  fields.push({
    name: ':octagonal_sign: Consider Disabling',
    value: summary.shouldDisable.map(s => `- ${s.name}`).join('\n').substring(0, 300),
    inline: false
  });
}

if (summary.proposalsCreated > 0) {
  fields.push({
    name: ':clipboard: Proposals Created',
    value: `${summary.proposalsCreated} proposals pending approval in #approvals`,
    inline: false
  });
}

const embed = {
  title: ':bar_chart: Weekly Strategy Tuning Report',
  description: `Analyzed ${summary.totalStrategies} strategies for the upcoming trading week.`,
  color: embedColor,
  fields: fields,
  footer: {
    text: 'WF-LEARN-02 Strategy Tuner | Sunday Pre-Week Analysis'
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    embed,
    summary,
    channelId: process.env.DISCORD_CEO_CHANNEL_ID || 'ceo-briefing'
  }
};

return {
  json: {
    error: 'No active strategies found for analysis',
    message: 'Please ensure strategies are configured and enabled in the system',
    analyzedAt: new Date().toISOString()
  }
};

const error = $json;

const errorEmbed = {
  title: ':warning: Strategy Tuner Error',
  description: 'WF-LEARN-02 encountered an error during weekly strategy analysis.',
  color: 15158332,
  fields: [
    {
      name: 'Error Message',
      value: error.execution?.error?.message?.substring(0, 1000) || 'Unknown error',
      inline: false
    },
    {
      name: 'Failed Node',
      value: error.execution?.error?.node?.name || 'Unknown',
      inline: true
    },
    {
      name: 'Execution ID',
      value: error.execution?.id || 'Unknown',
      inline: true
    }
  ],
  footer: {
    text: 'WF-LEARN-02 Error Handler'
  },
  timestamp: new Date().toISOString()
};

return { json: { embed: errorEmbed } };
